-- App Edge Functions backend contract.
-- This migration is additive and keeps Web/Auth data shared in the same Supabase project.

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS trigger AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 1. Persist daily rhythm scores generated by the App backend.
CREATE TABLE IF NOT EXISTS public.daily_rhythm_scores (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  record_date date NOT NULL,
  score numeric NOT NULL,
  confidence numeric,
  signals jsonb NOT NULL DEFAULT '[]'::jsonb,
  reasons jsonb NOT NULL DEFAULT '[]'::jsonb,
  actions jsonb NOT NULL DEFAULT '[]'::jsonb,
  model_version text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(user_id, record_date)
);

ALTER TABLE public.daily_rhythm_scores ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view own rhythm scores" ON public.daily_rhythm_scores;
DROP POLICY IF EXISTS "Users can insert own rhythm scores" ON public.daily_rhythm_scores;
DROP POLICY IF EXISTS "Users can update own rhythm scores" ON public.daily_rhythm_scores;
DROP POLICY IF EXISTS "Users can delete own rhythm scores" ON public.daily_rhythm_scores;

CREATE POLICY "Users can view own rhythm scores"
ON public.daily_rhythm_scores FOR SELECT TO authenticated
USING (auth.uid() = user_id);

CREATE POLICY "Users can insert own rhythm scores"
ON public.daily_rhythm_scores FOR INSERT TO authenticated
WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update own rhythm scores"
ON public.daily_rhythm_scores FOR UPDATE TO authenticated
USING (auth.uid() = user_id);

CREATE POLICY "Users can delete own rhythm scores"
ON public.daily_rhythm_scores FOR DELETE TO authenticated
USING (auth.uid() = user_id);

DROP TRIGGER IF EXISTS update_daily_rhythm_scores_updated_at ON public.daily_rhythm_scores;
CREATE TRIGGER update_daily_rhythm_scores_updated_at
BEFORE UPDATE ON public.daily_rhythm_scores
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

-- 2. Persist latest Watch payloads for phone/watch handoff and debugging.
CREATE TABLE IF NOT EXISTS public.watch_snapshots (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  record_date date NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  pushed_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(user_id, record_date)
);

ALTER TABLE public.watch_snapshots ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view own watch snapshots" ON public.watch_snapshots;
DROP POLICY IF EXISTS "Users can insert own watch snapshots" ON public.watch_snapshots;
DROP POLICY IF EXISTS "Users can update own watch snapshots" ON public.watch_snapshots;
DROP POLICY IF EXISTS "Users can delete own watch snapshots" ON public.watch_snapshots;

CREATE POLICY "Users can view own watch snapshots"
ON public.watch_snapshots FOR SELECT TO authenticated
USING (auth.uid() = user_id);

CREATE POLICY "Users can insert own watch snapshots"
ON public.watch_snapshots FOR INSERT TO authenticated
WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update own watch snapshots"
ON public.watch_snapshots FOR UPDATE TO authenticated
USING (auth.uid() = user_id);

CREATE POLICY "Users can delete own watch snapshots"
ON public.watch_snapshots FOR DELETE TO authenticated
USING (auth.uid() = user_id);

DROP TRIGGER IF EXISTS update_watch_snapshots_updated_at ON public.watch_snapshots;
CREATE TRIGGER update_watch_snapshots_updated_at
BEFORE UPDATE ON public.watch_snapshots
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

-- 3. Private App photo buckets. Users can access only objects under their own user id folder.
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES
  ('diet-photos', 'diet-photos', false, 10485760, ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif']),
  ('face-photos', 'face-photos', false, 10485760, ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif'])
ON CONFLICT (id) DO UPDATE
SET
  public = false,
  file_size_limit = EXCLUDED.file_size_limit,
  allowed_mime_types = EXCLUDED.allowed_mime_types;

DROP POLICY IF EXISTS "Users can read own app photos" ON storage.objects;
DROP POLICY IF EXISTS "Users can insert own app photos" ON storage.objects;
DROP POLICY IF EXISTS "Users can update own app photos" ON storage.objects;
DROP POLICY IF EXISTS "Users can delete own app photos" ON storage.objects;

CREATE POLICY "Users can read own app photos"
ON storage.objects FOR SELECT TO authenticated
USING (
  bucket_id IN ('diet-photos', 'face-photos')
  AND (storage.foldername(name))[1] = auth.uid()::text
);

CREATE POLICY "Users can insert own app photos"
ON storage.objects FOR INSERT TO authenticated
WITH CHECK (
  bucket_id IN ('diet-photos', 'face-photos')
  AND (storage.foldername(name))[1] = auth.uid()::text
);

CREATE POLICY "Users can update own app photos"
ON storage.objects FOR UPDATE TO authenticated
USING (
  bucket_id IN ('diet-photos', 'face-photos')
  AND (storage.foldername(name))[1] = auth.uid()::text
);

CREATE POLICY "Users can delete own app photos"
ON storage.objects FOR DELETE TO authenticated
USING (
  bucket_id IN ('diet-photos', 'face-photos')
  AND (storage.foldername(name))[1] = auth.uid()::text
);
